dashboard.definition:
{
  "title": "Windows Events",
  "description": "Windows operational health — event severity trends, top event codes, service state changes, and PowerShell activity",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_total": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_total"
      },
      "title": "Total Events",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_critical": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_critical"
      },
      "title": "Critical / Error",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_hosts": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_hosts"
      },
      "title": "Active Hosts",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_volume_by_log": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_volume_by_log"
      },
      "title": "Event Volume by Log",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_severity": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_severity"
      },
      "title": "Severity Distribution Over Time",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "critical": "#dc4e41",
          "error": "#dc4e41",
          "warning": "#f1813f",
          "information": "#0877a6"
        },
        "dataValuesDisplay": "off"
      }
    },
    "viz_top_events": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_top_events"
      },
      "title": "Top Event Codes",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22XmlWinEventLog%22%20EventCode%3D%22%24row.Event%20Code.value%24%22%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_service_events": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_service_events"
      },
      "title": "Service Events",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_powershell": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_powershell"
      },
      "title": "PowerShell Activity",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_rect_r1l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r1r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_rect_1": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_2": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_3": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/platform/#windows-events",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_total": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_critical": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" severity IN (\"critical\", \"error\") | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_hosts": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | eventstats dc(host) as window_dc | timechart span=1d dc(host) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]"
      }
    },
    "ds_volume_by_log": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | timechart span=1d count by source"
      }
    },
    "ds_severity": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | where isnotnull(severity) | timechart span=1d count by severity"
      }
    },
    "ds_top_events": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | eval log_name = replace(source, \"WinEventLog:\", \"\") | stats count as Events, dc(host) as Hosts, first(signature) as Description, first(severity) as Severity, first(log_name) as Source, latest(_time) as last_seen_ts by EventCode | eval \"Last Seen\" = strftime(last_seen_ts, \"%Y-%m-%d %H:%M:%S\") | sort -Events | head 30 | table EventCode, Description, Source, Severity, Events, Hosts, \"Last Seen\" | rename EventCode as \"Event Code\""
      }
    },
    "ds_service_events": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" source=\"WinEventLog:System\" EventCode IN (7036, 7034, 7031) | rex field=_raw \"<Data Name='param1'>(?<svc_name>[^<]+)</Data>\" | rex field=_raw \"<Data Name='param2'>(?<svc_state>[^<]+)</Data>\" | where isnotnull(svc_name) | stats count as Events latest(svc_state) as \"Last State\" by svc_name | sort -Events | head 20 | rename svc_name as \"Service Name\""
      }
    },
    "ds_powershell": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" source=\"WinEventLog:Powershell\" | timechart span=1d count as \"PowerShell Events\""
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "options": {
          "display": "fit-to-width",
          "height": 1321,
          "width": 1920,
          "backgroundColor": "#0d1117"
        },
        "structure": [
          {
            "item": "viz_nav_go",
            "type": "block",
            "position": {
              "x": 10,
              "y": 10,
              "w": 120,
              "h": 25
            }
          },
          {
            "item": "viz_kpi_rect_1",
            "type": "block",
            "position": {
              "x": 10,
              "y": 45,
              "w": 620,
              "h": 140
            }
          },
          {
            "item": "viz_kpi_rect_2",
            "type": "block",
            "position": {
              "x": 642,
              "y": 45,
              "w": 620,
              "h": 140
            }
          },
          {
            "item": "viz_kpi_rect_3",
            "type": "block",
            "position": {
              "x": 1274,
              "y": 45,
              "w": 636,
              "h": 140
            }
          },
          {
            "item": "viz_kpi_total",
            "type": "block",
            "position": {
              "x": 15,
              "y": 50,
              "w": 610,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_critical",
            "type": "block",
            "position": {
              "x": 647,
              "y": 50,
              "w": 610,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_hosts",
            "type": "block",
            "position": {
              "x": 1279,
              "y": 50,
              "w": 626,
              "h": 130
            }
          },
          {
            "item": "viz_rect_r1l",
            "type": "block",
            "position": {
              "x": 10,
              "y": 197,
              "w": 940,
              "h": 340
            }
          },
          {
            "item": "viz_volume_by_log",
            "type": "block",
            "position": {
              "x": 15,
              "y": 202,
              "w": 930,
              "h": 330
            }
          },
          {
            "item": "viz_rect_r1r",
            "type": "block",
            "position": {
              "x": 962,
              "y": 197,
              "w": 948,
              "h": 340
            }
          },
          {
            "item": "viz_severity",
            "type": "block",
            "position": {
              "x": 967,
              "y": 202,
              "w": 938,
              "h": 330
            }
          },
          {
            "item": "viz_rect_r2l",
            "type": "block",
            "position": {
              "x": 10,
              "y": 549,
              "w": 1900,
              "h": 400
            }
          },
          {
            "item": "viz_top_events",
            "type": "block",
            "position": {
              "x": 15,
              "y": 554,
              "w": 1890,
              "h": 390
            }
          },
          {
            "item": "viz_rect_r3l",
            "type": "block",
            "position": {
              "x": 10,
              "y": 961,
              "w": 940,
              "h": 340
            }
          },
          {
            "item": "viz_service_events",
            "type": "block",
            "position": {
              "x": 15,
              "y": 966,
              "w": 930,
              "h": 330
            }
          },
          {
            "item": "viz_rect_r3r",
            "type": "block",
            "position": {
              "x": 962,
              "y": 961,
              "w": 948,
              "h": 340
            }
          },
          {
            "item": "viz_powershell",
            "type": "block",
            "position": {
              "x": 967,
              "y": 966,
              "w": 938,
              "h": 330
            }
          },
          {
            "item": "viz_more_info",
            "type": "block",
            "position": {
              "x": 1770,
              "y": 10,
              "w": 140,
              "h": 25
            }
          }
        ],
        "type": "absolute"
      }
    },
    "options": {},
    "tabs": {
      "items": [
        {
          "label": "New tab",
          "layoutId": "layout_1"
        }
      ]
    }
  }
}
